-- SELECT STRING_AGG(t.name, ' ') AS [data types]
SELECT
  t.name,
  t.max_length,
  t.[precision],
  t.scale
FROM sys.types AS t
WHERE t.is_user_defined = 0
  AND t.is_table_type = 0
ORDER BY t.name;

SELECT CAST('<t a="42"><l/><r/></t>' AS XML);

SELECT CAST('<t a="42"><l/><r></t>' AS XML);

SELECT CAST('01234' AS char(3));

SELECT CAST(t.c AS char(10))
FROM (VALUES ('01234'),('0123456789')) AS t(c);

SELECT t.c,
       LEN(t.c)       AS chars,
       DATALENGTH(t.c) AS bytes
FROM   (VALUES (N'x'),
               (N'⚠'), -- ⚠ = U+26A0, in UTF8: 0xE2 0x9A 0xA0
               (N'👩🏾')
       ) AS t(c);

SELECT DATALENGTH(CAST('0123456789' AS varchar(5))) AS c1,
  DATALENGTH(CAST('012' AS varchar(5))) AS c2,
  DATALENGTH(CAST('012' AS char(5))) AS c3,
  LEN(CAST('012' AS char(5))) AS c4,
  LEN(CAST('012   ' AS char(5))) AS c5;

SET STATISTICS IO ON;
SET STATISTICS TIME ON;

SELECT POWER(CAST(2 as decimal), 100);

WITH one_million_rows AS (
  -- SELECT CAST(t.[value] AS decimal(8,0)) AS x
  SELECT CAST(t.[value] AS int) AS x
  FROM generate_series(0, 1000000) AS t
)
SELECT t.x + t.x AS [add]
FROM one_million_rows AS t;

SET STATISTICS IO OFF;
SET STATISTICS TIME OFF;

